module tb_TopModule;
    logic [15:0] in;
    logic [ 7:0] out_hi;
    logic [ 7:0] out_lo;

    TopModule dut (
        .in(in),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    initial begin
        // Test various inputs
        in = 16'h1234;
        #10;
        if (out_hi !== 8'h12 || out_lo !== 8'h34) begin
            $display("SELFTEST FAIL: in=16'h1234, got out_hi=%h, out_lo=%h (expected hi=12, lo=34)", out_hi, out_lo);
            $finish;
        end

        in = 16'h0000;
        #10;
        if (out_hi !== 8'h00 || out_lo !== 8'h00) begin
            $display("SELFTEST FAIL: in=16'h0000, got out_hi=%h, out_lo=%h", out_hi, out_lo);
            $finish;
        end

        in = 16'hFFFF;
        #10;
        if (out_hi !== 8'hFF || out_lo !== 8'hFF) begin
            $display("SELFTEST FAIL: in=16'hFFFF, got out_hi=%h, out_lo=%h", out_hi, out_lo);
            $finish;
        end

        in = 16'hA55A;
        #10;
        if (out_hi !== 8'hA5 || out_lo !== 8'h5A) begin
            $display("SELFTEST FAIL: in=16'hA55A, got out_hi=%h, out_lo=%h", out_hi, out_lo);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
